function sendKeysEscape(text) {
  const map = {
    "{": "{{}",
    "}": "{}}",
    "+": "{+}",
    "^": "{^}",
    "%": "{%}",
    "~": "{~}",
    "(": "{(}",
    ")": "{)}",
    "[": "{[}",
    "]": "{]}"
  };
  return text.replace(/[{}+^%~()[\]]/g, (ch) => map[ch] ?? ch);
}
function sendKeysToken(key) {
  const k = key.trim();
  if (!k) return null;
  const lower = k.toLowerCase();
  const named = {
    enter: "{ENTER}",
    return: "{ENTER}",
    tab: "{TAB}",
    esc: "{ESC}",
    escape: "{ESC}",
    backspace: "{BACKSPACE}",
    delete: "{DEL}",
    del: "{DEL}",
    insert: "{INS}",
    ins: "{INS}",
    home: "{HOME}",
    end: "{END}",
    pageup: "{PGUP}",
    pgup: "{PGUP}",
    pagedown: "{PGDN}",
    pgdn: "{PGDN}",
    up: "{UP}",
    arrowup: "{UP}",
    down: "{DOWN}",
    arrowdown: "{DOWN}",
    left: "{LEFT}",
    arrowleft: "{LEFT}",
    right: "{RIGHT}",
    arrowright: "{RIGHT}",
    space: " ",
    spacebar: " ",
    capslock: "{CAPSLOCK}",
    printscreen: "{PRTSC}"
  };
  if (named[lower]) return named[lower];
  if (/^f([1-9]|1[0-2])$/.test(lower)) return `{${k.toUpperCase()}}`;
  if (k.length === 1) return sendKeysEscape(k);
  return null;
}
function sendKeysForCombination(keyArg) {
  const parts = keyArg.split("+").map((p) => p.trim()).filter(Boolean);
  if (!parts.length) return null;
  let prefix = "";
  let main = "";
  for (const p of parts) {
    const lower = p.toLowerCase();
    if (lower === "ctrl" || lower === "control") {
      prefix += "^";
      continue;
    }
    if (lower === "alt") {
      prefix += "%";
      continue;
    }
    if (lower === "shift") {
      prefix += "+";
      continue;
    }
    if (lower === "win" || lower === "meta" || lower === "cmd" || lower === "super") return null;
    const token = sendKeysToken(p);
    if (!token) return null;
    main = token;
  }
  return prefix + main;
}
function xdotoolKeyForCombination(keyArg) {
  const parts = keyArg.split("+").map((p) => p.trim()).filter(Boolean);
  if (!parts.length) return null;
  const out = [];
  for (const p of parts) {
    const lower = p.toLowerCase();
    if (lower === "ctrl" || lower === "control") {
      out.push("ctrl");
      continue;
    }
    if (lower === "alt") {
      out.push("alt");
      continue;
    }
    if (lower === "shift") {
      out.push("shift");
      continue;
    }
    if (lower === "win" || lower === "meta" || lower === "cmd" || lower === "super") {
      out.push("super");
      continue;
    }
    const named = {
      enter: "Return",
      return: "Return",
      esc: "Escape",
      escape: "Escape",
      backspace: "BackSpace",
      delete: "Delete",
      del: "Delete",
      insert: "Insert",
      ins: "Insert",
      home: "Home",
      end: "End",
      pageup: "Prior",
      pgup: "Prior",
      pagedown: "Next",
      pgdn: "Next",
      up: "Up",
      arrowup: "Up",
      down: "Down",
      arrowdown: "Down",
      left: "Left",
      arrowleft: "Left",
      right: "Right",
      arrowright: "Right",
      space: "space",
      capslock: "Caps_Lock",
      printscreen: "Print"
    };
    if (named[lower]) {
      out.push(named[lower]);
      continue;
    }
    if (/^f([1-9]|1[0-2])$/.test(lower)) {
      out.push("F" + lower.slice(1));
      continue;
    }
    if (p.length === 1) {
      out.push(p);
      continue;
    }
    return null;
  }
  return out.join("+");
}
